      {
        "atom_id": "atom::f10ae71e3af0e5426782b275",
        "source_handle": "P0583",
        "field_path": [
          "study_summary_A",
          "research_scope"
        ],
        "value": "该研究针对晚期非小细胞肺癌（NSCLC）和皮肤黑色素瘤患者，评估健康供体粪便微生物群移植（FMT）联合一线免疫检查点抑制剂（ICI）治疗的临床疗效、安全性及机制。NSCLC队列接受抗PD-1单药治疗，黑色素瘤队列接受抗PD-1联合抗CTLA-4双免疫检查点抑制治疗。",
        "role": "evidence",
        "snapshot_ids": [
          "snapshot::3f08daede868f51719f44f75",
          "snapshot::cc9c61313270bf8ed21449cd",
          "snapshot::858e2e285637cdae2d18e8b5",
