        "field_path": [
          "review_planning_B",
          "scope_interpretation_cautions"
        ],
        "value": "工程菌的大部分应用仍处于临床前阶段，将其机制外推到当前临床实践时需明确标注其实验性质。",
        "role": "evidence",
        "snapshot_ids": [
